 "content": "def transform(grid):
    out=[r[:] for r in grid]
    for r in range(len(grid)):
        for k in (0,1):
            vals=[grid[r][3*b+k] for b in range(4)]
            counts={v: vals.count(v) for v in set(vals)}
            best=max(counts.values())
            # In ties, trust the leftmost strip as the reference.
            v=vals[0] if counts[vals[0]]==best else next(x for x in vals if counts[x]==best)
            for b in range(4): out[r][3*b+k]=v
    return out

